// Invert Binary Tree - ayotl.dev
#include <stdio.h>

typedef struct Tree {
    int val;
    struct Tree *left, *right;
} Tree;

Tree *invert(Tree *t) {
    if (!t)
        return NULL;
    // swap the children, inverted
    Tree *l = invert(t->left);
    t->left = invert(t->right);
    t->right = l;
    return t;
}

void show(Tree *t) {  // level by level
    Tree *q[16] = {t};
    for (int h = 0, n = 1; h < n; h++) {
        printf("%d ", q[h]->val);
        if (q[h]->left)
            q[n++] = q[h]->left;
        if (q[h]->right)
            q[n++] = q[h]->right;
    }
    printf("\n");
}

int main(void) {
    Tree a = {1}, b = {3}, c = {6}, d = {9};
    Tree l = {2, &a, &b}, r = {7, &c, &d};
    Tree root = {4, &l, &r};
    show(&root);
    show(invert(&root));
    return 0;
}

