// Max Depth of Binary Tree - ayotl.dev
#include <stdio.h>

typedef struct Tree {
    int val;
    struct Tree *left, *right;
} Tree;

int max_depth(Tree *t) {
    if (!t)
        return 0;  // empty tree
    int l = max_depth(t->left);
    int r = max_depth(t->right);
    // this node + the deeper subtree
    return 1 + (l > r ? l : r);
}

int main(void) {
    Tree a = {15}, b = {7}, c = {9};
    Tree d = {20, &a, &b};
    Tree root = {3, &c, &d};
    Tree y = {2}, x = {1, NULL, &y};
    printf("%d\n", max_depth(&root));
    printf("%d\n", max_depth(&x));
    return 0;
}

// Linked List Cycle - ayotl.dev
#include <stdio.h>

typedef struct Node {
    int val;
    struct Node *next;
} Node;

int has_cycle(Node *head) {
    // tortoise: 1 step, hare: 2 steps
    Node *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast)
            return 1;  // hare lapped it
    }
    return 0;  // hare hit the end
}

int main(void) {
    Node d = {-4, NULL}, c = {0, &d};
    Node b = {2, &c}, a = {3, &b};
    d.next = &b;  // -4 points back to 2
    puts(has_cycle(&a) ? "true" : "false");
    d.next = NULL;
    puts(has_cycle(&a) ? "true" : "false");
    return 0;
}

// Maximum Subarray - ayotl.dev
#include <stdio.h>

int max_subarray(const int *a, int n) {
    // Kadane: best sum ending right here
    int cur = a[0], best = a[0];
    for (int i = 1; i < n; i++) {
        // extend the run, or start over
        if (cur + a[i] > a[i])
            cur = cur + a[i];
        else
            cur = a[i];
        if (cur > best)
            best = cur;
    }
    return best;
}

