class Node:
    def __init__(self, val, next=None):
        self.val, self.next = val, next


def merge(a, b):
    # dummy head: no special case for 1st
    head = tail = Node(0)
    while a and b:
        # take the smaller node, advance it
        if a.val <= b.val:
            tail.next, a = a, a.next
        else:
            tail.next, b = b, b.next
        tail = tail.next
    tail.next = a or b  # append leftovers
    return head.next


def build(vals):
    head = None
    for v in reversed(vals):
        head = Node(v, head)
    return head


