// Merge Two Sorted Lists - ayotl.dev
#include <stdio.h>

typedef struct Node {
    int val;
    struct Node *next;
} Node;

Node *merge(Node *a, Node *b) {
    // dummy head on the stack
    Node head = {0, NULL}, *tail = &head;
    while (a && b) {
        // splice in the smaller node
        if (a->val <= b->val) {
            tail->next = a; a = a->next;
        } else {
            tail->next = b; b = b->next;
        }
        tail = tail->next;
    }
    tail->next = a ? a : b;  // leftovers
    return head.next;
}

int main(void) {
    Node a3 = {4, NULL}, a2 = {2, &a3};
    Node a1 = {1, &a2};
    Node b3 = {4, NULL}, b2 = {3, &b3};
    Node b1 = {1, &b2};
    for (Node *n = merge(&a1, &b1); n;
         n = n->next)
        printf(n->next ? "%d -> " : "%d\n",
               n->val);
    return 0;
}

