def is_palindrome(s):
    # two pointers walking inward
    i, j = 0, len(s) - 1
    while i < j:
        if not s[i].isalnum():
            i += 1  # skip punctuation
        elif not s[j].isalnum():
            j -= 1
        elif s[i].lower() != s[j].lower():
            return False  # mismatch
        else:
            i, j = i + 1, j - 1
    return True


