#include <ctype.h>
#include <stdio.h>
#include <string.h>

int is_palindrome(const char *s) {
    // two pointers walking inward
    int i = 0, j = strlen(s) - 1;
    while (i < j) {
        if (!isalnum(s[i]))
            i++;  // skip punctuation
        else if (!isalnum(s[j]))
            j--;
        else if (tolower(s[i++]) !=
                 tolower(s[j--]))
            return 0;  // mismatch
    }
    return 1;
}

