// Reverse Linked List - ayotl.dev
#include <stdio.h>

typedef struct Node {
    int val;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;  // save
        head->next = prev;  // flip arrow
        prev = head;
        head = next;
    }
    return prev;  // old tail = new head
}

