    for (int i = 0; i < 5; i++) {
        n[i].val = i + 1;
        n[i].next = i < 4 ? &n[i + 1]
                          : NULL;
    }
    for (Node *p = reverse(n); p;
         p = p->next)
        printf(p->next ? "%d -> " : "%d\n",
               p->val);
    return 0;
}

