#include <stdio.h>

long climb(int n) {
    // ways(n) = ways(n-1) + ways(n-2):
    // Fibonacci, keep just the last two
    long a = 1, b = 1;
    for (int i = 0; i < n; i++) {
        long t = a + b;
        a = b;
        b = t;
    }
    return a;
}

