// Contains Duplicate - ayotl.dev
#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    return *(int *)a - *(int *)b;
}

int has_dup(int *a, int n) {
    // sorted, equal values sit together
    qsort(a, n, sizeof(int), cmp);
    for (int i = 1; i < n; i++)
        if (a[i] == a[i - 1])
            return 1;
    return 0;
}

