    int b[] = {1, 2, 3, 4};
    puts(has_dup(a, 4) ? "true" : "false");
    puts(has_dup(b, 4) ? "true" : "false");
    return 0;
}

# Valid Anagram - ayotl.dev
def is_anagram(s, t):
    if len(s) != len(t):
        return False
    # +1 for letters of s, -1 for t
    count = {}
    for a, b in zip(s, t):
        count[a] = count.get(a, 0) + 1
        count[b] = count.get(b, 0) - 1
    # anagram: every count is back to 0
    return not any(count.values())


print(is_anagram("anagram", "nagaram"))
print(is_anagram("rat", "car"))

