#include <stdio.h>

int is_anagram(const char *s,
               const char *t) {
    int count[26] = {0};  // one per letter
    for (; *s; s++)
        count[*s - 'a']++;
    for (; *t; t++)
        count[*t - 'a']--;
    // anagram: every count is back to 0
    for (int i = 0; i < 26; i++)
        if (count[i] != 0)
            return 0;
    return 1;
}

