// Buy and Sell Stock - ayotl.dev
#include <stdio.h>

int max_profit(const int *p, int n) {
    int low = p[0];  // cheapest so far
    int best = 0;
    for (int i = 1; i < n; i++) {
        if (p[i] < low)
            low = p[i];  // new low: buy
        else if (p[i] - low > best)
            best = p[i] - low;  // sell
    }
    return best;
}

