    int b[] = {7, 6, 4, 3, 1};
    printf("%d\n", max_profit(a, 6));
    printf("%d\n", max_profit(b, 5));
    return 0;
}

# Valid Parentheses - ayotl.dev
def is_valid(s):
    # each closer -> the opener it needs
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in s:
        if ch in pairs:
            # the last opener must match
            if not stack:
                return False
            if stack.pop() != pairs[ch]:
                return False
        else:
            stack.append(ch)  # remember it
    # valid only if nothing is left open
    return not stack


for s in ["()", "([]{})", "(]", "([)]"]:
    print(s, is_valid(s))

// Valid Parentheses - ayotl.dev
#include <stdio.h>

int is_valid(const char *s) {
    char st[256];  // stack of openers
    int top = 0;
    for (; *s; s++) {
        char c = *s;
        if (c == '(' || c == '[' ||
            c == '{') {
            st[top++] = c;  // push
            continue;
        }
        // the opener this closer needs
        char want = c == ')' ? '('
                  : c == ']' ? '[' : '{';
        if (top == 0 || st[--top] != want)
            return 0;
    }
    return top == 0;  // nothing left open
}

int main(void) {
    const char *t[] = {"()", "([]{})",
                       "(]", "([)]"};
    for (int i = 0; i < 4; i++)
        printf("%s %s\n", t[i],
               is_valid(t[i]) ? "true"
                              : "false");
    return 0;
}

