#include <stdio.h>

// a tiny hash table: value -> index
#define SIZE 64

typedef struct { int key, idx, used; } Slot;

static int slot(int key) {
    return (key & 0x7fffffff) % SIZE;
}

void two_sum(int *nums, int n, int target) {
    Slot t[SIZE] = {0};  // seen values
    for (int i = 0; i < n; i++) {
        // the value we still need
        int rest = target - nums[i];
        int h = slot(rest);
        while (t[h].used) {
            if (t[h].key == rest) {
                printf("[%d, %d]\n",
                       t[h].idx, i);
                return;
            }
            h = (h + 1) % SIZE;
        }
        // not found: store this one
        h = slot(nums[i]);
        while (t[h].used)
            h = (h + 1) % SIZE;
        t[h].key = nums[i];
        t[h].idx = i;
        t[h].used = 1;
    }
    printf("[]\n");
}

int main(void) {
    int a[] = {2, 7, 11, 15};
    int b[] = {3, 2, 4};
    int c[] = {3, 3};
    two_sum(a, 4, 9);
    two_sum(b, 3, 6);
    two_sum(c, 2, 6);
    return 0;
}

